insert into arrival_info (case_id, case_no, case_title, 
  arrival_money, arrival_time, user_commission_id,loan_amount,interest_amount,still_amount,insurance_amount
  )
values (#{caseId,jdbcType=BIGINT}, #{caseNo,jdbcType=VARCHAR}, #{caseTitle,jdbcType=VARCHAR}, 
  #{arrivalMoney,jdbcType=DOUBLE}, #{arrivalTime,jdbcType=TIMESTAMP}, #{userCommissionId,jdbcType=BIGINT},#{loanAmount,jdbcType=DOUBLE}
  ,#{interestAmount,jdbcType=DOUBLE},#{stillAmount,jdbcType=DOUBLE},#{insuranceAmount,jdbcType=DOUBLE}
