select
count(1)
from arrival_info


        and case_id = #{caseId,jdbcType=BIGINT}


        and case_no = #{caseNo,jdbcType=VARCHAR}


        and case_title = #{caseTitle,jdbcType=VARCHAR}


        and arrival_money = #{arrivalMoney,jdbcType=DOUBLE}


        and arrival_time = #{arrivalTime,jdbcType=TIMESTAMP}


        and user_commission_id = #{userCommissionId,jdbcType=BIGINT}

select
a.id as id,
a.case_id as caseId,
a.case_no as caseNo,
a.case_title as caseTitle,
a.arrival_money as arrivalMoney,
a.arrival_time as arrivalTime,
a.user_commission_id as userCommissionId,
u.user_name as userCommissionName
from arrival_info a
left join user_info u on a.user_commission_id = u.user_id


        and case_id = #{caseId,jdbcType=BIGINT}


        and case_no = #{caseNo,jdbcType=VARCHAR}


        and case_title = #{caseTitle,jdbcType=VARCHAR}


        and arrival_money = #{arrivalMoney,jdbcType=DOUBLE}


        and arrival_time = #{arrivalTime,jdbcType=TIMESTAMP}


        and user_commission_id = #{userCommissionId,jdbcType=BIGINT}


order by id desc limit #{pageIndex} , #{pageSize}

select a.id as id, a.case_id as caseId, a.case_no as caseNo, a.case_title as caseTitle, a.arrival_money as arrivalMoney, a.arrival_time as arrivalTime, a.user_commission_id as userCommissionId, u.user_name as userCommissionName from arrival_info a left join user_info u on a.user_commission_id = u.user_id
and case_no = #{caseNo,jdbcType=VARCHAR}
and a.loan_amount > 0
